  1	import type { StoredLicense, StoredPack, StoredRun, SyncState } from "../storage/db.ts";
  2	import { diff, type Entry } from "./diff.ts";
  3	import { hashText } from "./hash.ts";
  4	import type { RunEvent } from "@runlog/engine";
  5	import { SyncError, type Api, type RemoteLicense, type RemotePack, type SessionEvent, type SyncFailure } from "./client.ts";
  6	import { merge, nameFrom, pendingEvents, stampIds, tailSeq } from "./log.ts";
  7	import { syncBus } from "./bus.ts";
  8	import { settlePurchases } from "./purchases.ts";
  9	import { loadPackText } from "@runlog/rules-schema";
 10	
 11	/**
 12	 * The engine: manifest, diff, act, record.
 13	 *
 14	 * One pass looks like this. Ask the server what it holds. Runs are
 15	 * sessions with an append-only log: send what this device made and has not
 16	 * had numbered, take back what the server has past what this device saw,
 17	 * and fold the two together, nothing here is ever replaced whole. Packs
 18	 * travel only where the player turned the pack's own switch on, so
 19	 * untoggled text never leaves, and never a sealed copy at all; license keys
 20	 * always, because a key is what lets the next device open the file the
 21	 * player already paid for. Diff those two. Push, pull, delete and purge as
 22	 * the plan says, telling the app about anything that arrived.
 23	 *
 24	 * Nothing here throws. Every failure becomes a status the header can show,
 25	 * which is the same rule storage keeps: losing sync is survivable, losing
 26	 * the session is not. One pass at a time; a request to sync while a pass is
 27	 * running is remembered and honored once, afterwards.
 28	 */
 29	
 30	export type SyncStatus = "idle" | "syncing" | "synced" | SyncFailure;
 31	
 32	export interface Report {
 33	  status: SyncStatus;
 34	  pushed: number;
 35	  pulled: number;
 36	  at: string;
 37	}
