 63	/** What a license's fingerprint covers: the key and what it was matched on. */
 64	const licenseText = (l: { key: string; ref?: string; title?: string }) => JSON.stringify([l.key, l.ref ?? "", l.title ?? ""]);
 65	
 66	export function createEngine(api: Api, db: SyncDb, now: () => string = () => new Date().toISOString()): Engine {
 67	  let inFlight: Promise<Report> | null = null;
 68	  let again = false;
 69	  let last: Report | null = null;
 70	
 71	  async function fingerprint<T extends { updatedAt: string; deletedAt?: string }>(
 72	    items: T[],
 73	    id: (x: T) => string,
 74	    text: (x: T) => string,
 75	    known: Map<string, SyncState>,
 76	  ): Promise<Entry[]> {
 77	    const out: Entry[] = [];
 78	    for (const item of items) {
 79	      const key = id(item);
 80	      const seen = known.get(key);
 81	      // A fingerprint the server confirmed for this very stamp is still good;
 82	      // hashing a long log on every pass is the cost this saves.
 83	      const hash = seen && seen.updatedAt === item.updatedAt && !item.deletedAt ? seen.hash : await hashText(text(item));
 84	      out.push({
 85	        id: key,
 86	        updatedAt: item.updatedAt,
 87	        hash,
 88	        ...(item.deletedAt ? { deletedAt: item.deletedAt } : {}),
 89	      });
 90	    }
 91	    return out;
 92	  }
 93	
 94	  async function pass(): Promise<Report> {
 95	    const at = now();
 96	    let pushed = 0;
 97	    let pulled = 0;
 98	    try {
 99	      const remote = await api.manifest();
100	      const known = new Map((await db.listSyncState()).map((s) => [s.id, s]));
101	
102	      // ---- sessions: send my outbox, take their tail ----
103	      const runs = await db.listRuns();
104	      const remoteSessions = new Map(remote.sessions.map((s) => [s.id, s]));
105	      const pulledRuns: string[] = [];
106	      const seen = new Set<string>();
107	      // One run's trouble is that run's: the rest of the pass goes on, and
108	      // the pass says so at the end. Only the connection and the sign-in
109	      // stop everything.
110	      let troubled = false;
111	
112	      for (const local of runs) {
113	        seen.add(local.runId);
114	        const theirs = remoteSessions.get(local.runId);
115	        try {
116	          if (local.deletedAt) {
117	            // Forgotten here. Tell the server once, then let the tombstone go.
118	            if (theirs && !theirs.deletedAt) await api.deleteSession(local.runId);
119	            await db.purgeRun(local.runId);
120	            await db.forgetSyncState(local.runId);
121	            continue;
122	          }
123	          if (theirs?.deletedAt) {
124	            // Ended for everyone by its owner: this copy goes too.
125	            await db.purgeRun(local.runId);
126	            await db.forgetSyncState(local.runId);
127	            pulledRuns.push(local.runId);
128	            continue;
129	          }
130	
131	          const stamped = await stampIds(local.runId, local.events as RunEvent[]);
132	          const pending = pendingEvents(stamped);
133	          const before = tailSeq(stamped);
134	          /**
135	           * How far along the server's counter this device has already
136	           * caught up: the log's own last number, or the counter the
137	           * manifest showed when a fetch came back with nothing behind it.
138	           *
139	           * The two part company after an undo, which takes an event out of
140	           * the log and leaves the session's counter where it was. That gap
141	           * is legitimate and permanent. Read as "somebody else has moved",
142	           * it had this device fetch nothing every pass, for as long as the
143	           * run was open.
144	           */
145	          const seenTail = Math.max(before, local.seq ?? 0);
146	          let serverTail = theirs?.seq ?? 0;
147	          let incoming: SessionEvent[] = [];
148	          let role = local.role;
149	          let members = local.members;
150	          let shared = local.shared;
151	          let asks = local.asks;
152	
153	          if (!theirs) {
154	            // The server has never heard of it, or no longer lists it for
155	            // this account: start the session with the whole log, numbered
156	            // afresh. If another device got there first, take its tail and
157	            // send what is still pending against it.
158	            const created = await api.createSession({
159	              id: local.runId,
160	              packId: local.packId,
161	              packVersion: local.packVersion,
162	              ...(local.packTitle ? { packTitle: local.packTitle } : {}),
163	              ...(nameFrom(stamped) ? { name: nameFrom(stamped)! } : {}),
164	              events: stamped,
165	            });
166	            if (created) {
167	              incoming = created.events;
168	              role = "owner";
169	              pushed += 1;
170	            } else {
171	              const got = await api.getSession(local.runId, 0);
172	              if (got) {
173	                incoming = got.events;
174	                members = got.members;
175	                shared = got.session.shared;
176	                asks = got.session.asks ?? null;
177	                const merged = merge(stamped, incoming as unknown as RunEvent[]);
178	                const still = pendingEvents(merged);
179	                if (still.length > 0) incoming = [...incoming, ...(await api.appendEvents(local.runId, still)).appended];
180	              }
181	            }
182	          } else {
183	            // How far the server's log goes: the manifest's word, or the
184	            // append's, whichever is later.
185	            if (pending.length > 0) {
186	              const sent = await api.appendEvents(local.runId, pending);
187	              incoming = sent.appended;
188	              serverTail = Math.max(serverTail, sent.seq);
189	              pushed += 1;
190	              const renamed = pending.some((e) => e.t === "RunRenamed");
191	              if (renamed) await api.patchSession(local.runId, { name: nameFrom(stamped) ?? "" });
192	            }
193	            // Anything numbered past what this device has caught up to and
194	            // not among what just came back is somebody else's: fetch from
195	            // where this device's log ends.
196	            if (serverTail > seenTail + incoming.length) {
197	              const got = await api.getSession(local.runId, before);
198	              if (got) {
199	                incoming = [...incoming, ...got.events];
200	                members = got.members;
201	                shared = got.session.shared;
202	                asks = got.session.asks ?? null;
203	              }
204	            }
205	            if (theirs) role = theirs.role;
206	          }
207	
208	          const merged = merge(stamped, incoming as unknown as RunEvent[]);
209	          /**
210	           * What the record carries besides its log, and which only the
211	           * server can say: who this account is in the run, who else is in
212	           * it, whether it is shared, what its ask key is.
213	           *
214	           * Kept apart from the log because the app has to hear about these
215	           * and must not hear about its own moves coming back numbered. A
216	           * run started here is pushed, answered with a role, and every
217	           * event that comes back is this device's own: nothing arrived, so
218	           * the run was left out of the news, and news with nothing in it is
219	           * dropped. Storage said `owner` while the screen still said
220	           * nothing, and the panel that waits on a role waited for a reload.
221	           *
222	           * By value, never by identity: every fetch hands back a fresh
223	           * members list, and a new object saying the old thing is not news.
224	           */
225	          const aboutTheRun =
226	            JSON.stringify(members ?? null) !== JSON.stringify(local.members ?? null) ||
227	            role !== local.role ||
228	            shared !== local.shared ||
229	            JSON.stringify(asks ?? null) !== JSON.stringify(local.asks ?? null);
230	          /**
231	           * Where the server's counter stands as far as this device knows:
232	           * its own log's last number, or the counter the manifest showed
233	           * while the server handed back nothing behind it. Written even
234	           * when nothing else about the run moved, because it is what the
235	           * next pass reads to know the gap has already been looked at.
236	           */
237	          const caughtUp = Math.max(tailSeq(merged), serverTail);
238	          const changed =
239	            aboutTheRun ||
240	            merged.length !== local.events.length ||
241	            tailSeq(merged) !== before ||
242	            stamped !== local.events ||
243	            caughtUp !== (local.seq ?? 0);
244	          if (changed) {
245	            await db.saveRun({
246	              ...local,
247	              events: merged,
248	              seq: caughtUp,
249	              ...(role ? { role } : {}),
250	              ...(members ? { members } : {}),
251	              ...(typeof shared === "boolean" ? { shared } : {}),
252	              ...(asks !== undefined ? { asks } : {}),
253	              updatedAt: theirs && theirs.updatedAt > local.updatedAt ? theirs.updatedAt : local.updatedAt,
254	            });
255	            const mine = new Set(pending.map((e) => e.id));
256	            const fromElsewhere = incoming.some((e) => e.seq > before && !mine.has(e.id));
257	            // The count is about events arriving; the news is about a record
258	            // the app is holding going stale. They are not the same question,
259	            // and answering both with the first one is what hid the role.
260	            if (fromElsewhere) pulled += 1;
261	            if (fromElsewhere || aboutTheRun) pulledRuns.push(local.runId);
262	          }
263	        } catch (error) {
264	          if (error instanceof SyncError && (error.kind === "offline" || error.kind === "unauthorized")) throw error;
265	          troubled = true;
266	        }
267	      }
268	
269	      // Sessions the server has that this device does not: take them whole.
270	      for (const theirs of remote.sessions) {
271	        if (seen.has(theirs.id) || theirs.deletedAt) continue;
272	        const got = await api.getSession(theirs.id, 0);
273	        if (!got) continue;
274	        await db.saveRun({
275	          runId: theirs.id,
276	          packId: theirs.packId,
277	          packVersion: theirs.packVersion,
278	          ...(theirs.packTitle ? { packTitle: theirs.packTitle } : {}),
279	          events: got.events,
280	          updatedAt: theirs.updatedAt,
281	          seq: tailSeq(got.events as unknown as RunEvent[]),
282	          role: theirs.role,
283	          members: got.members,
284	        });
285	        pulledRuns.push(theirs.id);
286	        pulled += 1;
287	      }
288	      syncBus.pulled("run", pulledRuns);
289	
290	      // ---- packs: only the ones the player said may travel ----
291	      // A sealed copy is left out even from the tombstones: the server is
292	      // not told it exists, and `forget` purges it outright for that reason.
293	      // And the server's row under the same id, a free copy of the same
294	      // pack, or the tombstone of one, is about that copy, not this one:
295	      // it must neither overwrite nor purge what was bought, so it is left
296	      // out of the plan while the sealed copy is on the shelf.
297	      const allPacks = await db.listAllPacks();
298	      const sealedHere = new Set(allPacks.filter((p) => p.sealed && !p.deletedAt).map((p) => p.id));
299	      const packs = allPacks.filter((p) => !p.sealed && (p.sync || p.deletedAt));
300	      const byPack = new Map(packs.map((p) => [p.id, p]));
301	      const packPlan = diff(
302	        await fingerprint(
303	          packs,
304	          (p) => p.id,
305	          (p) => p.source,
306	          known,
307	        ),
308	        remote.packs.filter((p) => !sealedHere.has(p.id)),
309	      );
310	      const remotePacks = new Map(remote.packs.map((p) => [p.id, p]));
311	
312	      for (const id of packPlan.push) {
313	        const local = byPack.get(id)!;
314	        const hash = await hashText(local.source);
315	        const remotePack: RemotePack = {
316	          id,
317	          title: local.title,
318	          version: local.version,
319	          format: local.format,
320	          filename: local.filename,
321	          importedAt: local.importedAt,
322	          updatedAt: local.updatedAt,
323	          hash,
324	          source: local.source,
325	          ...(local.origin ? { origin: local.origin === "catalog" ? "marketplace" : local.origin } : {}),
326	          // Either spelling, since a record written before the rename may not
327	          // have passed through storage since.
328	          ...((local.marketplace ?? local.catalog) ? { marketplace: (local.marketplace ?? local.catalog)! } : {}),
329	          // The license's word rides with the text, so the server can hand
330	          // the pack to a stranger with a live link only where it may.
331	          shareable: shareableOf(local),
332	        };
