370	      // A row here to drop, or nothing to do. The server keeps its
371	      // tombstone for a pack deleted anywhere, and a device that purged its
372	      // own copy passes ago has nothing left to forget: planned again every
373	      // pass, it was a delete against storage for a row already gone and a
374	      // "pack arrived" for every tombstone the account held, every pass.
375	      const here = new Set(allPacks.map((p) => p.id));
