379	        await db.forgetSyncState(id);
380	        pulledPacks.push(id);
381	      }
382	      for (const id of packPlan.deleteRemote) {
383	        await api.deletePack(id);
384	        await db.purgePack(id);
385	        await db.forgetSyncState(id);
386	      }
387	      for (const id of packPlan.purge) {
388	        await db.purgePack(id);
389	        await db.forgetSyncState(id);
390	      }
391	      syncBus.pulled("pack", pulledPacks);
392	
393	      // ---- licenses: small, and always ----
394	      const licenses = await db.listLicenses();
