414	        } else {
415	          licensePlan.pull.push(id);
416	        }
417	      }
418	      const pulledLicenses: string[] = [];
419	      for (const id of licensePlan.pull) {
420	        const theirs = await api.getLicense(id);
421	        if (!theirs) continue;
422	        await db.saveLicense({
423	          packId: theirs.id,
424	          key: theirs.key,
425	          ...(theirs.ref ? { ref: theirs.ref } : {}),
426	          ...(theirs.title ? { title: theirs.title } : {}),
427	          updatedAt: theirs.updatedAt,
428	        });
