463	  /**
464	   * One push, and one re-think on a conflict: the server holds a version
465	   * this pass did not know about. If theirs is newer, pulling is the right
466	   * answer; if mine is, push again without the precondition.
467	   */
468	  async function pushOnce(put: () => Promise<Entry>, theirs: Entry | undefined, mineUpdatedAt: string): Promise<Entry | null> {
469	    try {
470	      return await put();
471	    } catch (error) {
472	      if (!(error instanceof SyncError) || error.kind !== "conflict") throw error;
473	      const server = error.entry ?? theirs;
474	      if (server && server.updatedAt > mineUpdatedAt) return null;
475	      return put();
476	    }
477	  }
478	
479	  return {
480	    sync() {
481	      if (inFlight) {
482	        again = true;
483	        return inFlight;
484	      }
485	      inFlight = (async () => {
486	        let report = await pass();
487	        while (again) {
488	          again = false;
489	          report = await pass();
490	        }
491	        last = report;
492	        inFlight = null;
493	        return report;
494	      })();
495	      return inFlight;
496	    },
497	    last: () => last,
498	  };
499	}
