501	/** The storage module, in the shape the engine wants. */
502	export async function storageDb(): Promise<SyncDb> {
503	  const db = await import("../storage/db.ts");
504	  return {
505	    listRuns: db.listRuns,
506	    loadRun: db.loadRun,
507	    saveRun: db.saveRun,
508	    purgeRun: db.purgeRun,
509	    listAllPacks: db.listAllPacks,
510	    loadPack: db.loadPack,
511	    savePack: db.savePack,
512	    purgePack: db.purgePack,
513	    listLicenses: db.listLicenses,
514	    saveLicense: db.saveLicense,
515	    purgeLicense: db.purgeLicense,
516	    listSyncState: db.listSyncState,
517	    putSyncState: db.putSyncState,
518	    forgetSyncState: db.forgetSyncState,
519	  };
520	}
521	
522	/** Whether a pack's license lets its text travel to other people; unknown reads as no. */
523	function shareableOf(pack: StoredPack): boolean {
524	  try {
525	    const parsed = loadPackText(pack.source, pack.format);
526	    return parsed.ok ? parsed.pack.license.redistributable !== false : false;
527	  } catch {
528	    return false;
529	  }
530	}

