 1	/**
 2	 * How the rest of the app and the sync engine hear about each other.
 3	 *
 4	 * Two kinds of news: something changed here (the run hook wrote a log, a
 5	 * pack was imported or forgotten, a license key was typed), and something
 6	 * arrived from elsewhere (the engine pulled a run, a pack or a license). Neither side imports the other; both talk
 7	 * to this. Deliberately tiny, a Map of listeners, because the alternative
 8	 * is a state library for two events.
 9	 */
10	
11	export type Kind = "run" | "pack" | "license";
12	
13	export type SyncNews =
14	  | { t: "localChange"; kind: Kind; id: string }
15	  | { t: "pulled"; kind: Kind; ids: string[] }
16	  /** Something at the table of a watched run that is not a move; see the socket's `Gesture`. */
17	  | { t: "gesture"; id: string; kind: string; data: Record<string, unknown>; from?: string; at: string }
18	  /** A deck of this account's own pressing something; see the socket's `Drive`. */
19	  | { t: "drive"; from: string; run: string; seq: number; ref: string; press: string; move?: string; answer?: Record<string, unknown> };
20	
21	type Listener = (news: SyncNews) => void;
22	
23	const listeners = new Set<Listener>();
24	
25	export const syncBus = {
26	  subscribe(listener: Listener): () => void {
27	    listeners.add(listener);
28	    return () => listeners.delete(listener);
29	  },
30	  emit(news: SyncNews): void {
31	    for (const l of listeners) l(news);
32	  },
33	  localChange(kind: Kind, id: string): void {
34	    syncBus.emit({ t: "localChange", kind, id });
35	  },
36	  pulled(kind: Kind, ids: string[]): void {
37	    if (ids.length > 0) syncBus.emit({ t: "pulled", kind, ids });
38	  },
39	};

