  // What the watchers and the table sent: read when the panel opens, on
  // every pull of this run (the socket rings for a reaction), and every so
  // often.
  useEffect(() => {
    if (!api) return;
    let live = true;
    const read = () =>
      void api.reactions(run.runId).then(
        (r) => live && setReactions(r),
        () => {},
      );
    read();
    const every = window.setInterval(read, 15_000);
    const off = syncBus.subscribe((news) => {
      if (news.t === "pulled" && news.kind === "run" && news.ids.includes(run.runId)) read();
    });
    return () => {
      live = false;
      window.clearInterval(every);
      off();
    };
=== Asks ===
  // every pull of this run, and every so often in case the socket is down.
  useEffect(() => {
    if (!api || !taking) return;
    let live = true;
    const read = () =>
      void api.asks(record.runId).then(
        (a) => live && setAsks(a),
        () => {},
      );
    read();
    const every = window.setInterval(read, 15_000);
    const off = syncBus.subscribe((news) => {
      if (news.t === "gesture" && news.id === record.runId && (news.kind === "ask" || news.kind === "asked")) read();
      if (news.t === "pulled" && news.kind === "run" && news.ids.includes(record.runId)) read();
    });
    return () => {
      live = false;
      window.clearInterval(every);
      off();
    };
  }, [api, taking, record.runId]);

